import React, { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { NavTree, theme, useSidebar } from '@atlantis/shared';
import type { NavEntry, NavigationConfig } from '@atlantis/shared';
import { Clock, Star, ChevronRight } from 'lucide-react';

// ─── Storage helpers ──────────────────────────────────────────────────────────

function loadStored(key: string): NavEntry[] {
  try { return JSON.parse(localStorage.getItem(key) ?? '[]'); }
  catch { return []; }
}

function pushRecent(key: string, entry: NavEntry, current: NavEntry[]): NavEntry[] {
  const next = [entry, ...current.filter((e) => e.id !== entry.id)].slice(0, 10);
  localStorage.setItem(key, JSON.stringify(next));
  return next;
}

function toggleFav(key: string, entry: NavEntry, current: NavEntry[]): NavEntry[] {
  const isFav = current.some((e) => e.id === entry.id);
  const next = isFav ? current.filter((e) => e.id !== entry.id) : [...current, entry];
  localStorage.setItem(key, JSON.stringify(next));
  return next;
}

