// ─── QuickSection ─────────────────────────────────────────────────────────────

interface QuickSectionProps {
  title: string;
  icon: React.ReactNode;
  entries: NavEntry[];
  activeId: string | null;
  onSelect: (entry: NavEntry) => void;
  favorites: NavEntry[];
  onToggleFav: (entry: NavEntry) => void;
  collapsed: boolean;
}

function QuickSection({ title, icon, entries, activeId, onSelect, favorites, onToggleFav, collapsed }: QuickSectionProps) {
  const [open, setOpen] = useState(false);
  if (!entries.length) return null;

  return (
    <SectionWrap>
      <SectionBtn collapsed={collapsed} onClick={() => { if (!collapsed) setOpen((o) => !o); }}>
        <SectionLeft collapsed={collapsed}>
          {icon}
          <SectionLabel collapsed={collapsed}>{title}</SectionLabel>
        </SectionLeft>
        <Chevron open={open} collapsed={collapsed}>
          <ChevronRight size={12} />
        </Chevron>
      </SectionBtn>
      <SectionBody open={open && !collapsed}>
        <SectionInner>
          {entries.map((entry) => {
            const isFav = favorites.some((f) => f.id === entry.id);
            return (
              <EntryRow key={entry.id}>
                <EntryBtn active={activeId === entry.id} onClick={() => onSelect(entry)}>
                  {entry.name}
                </EntryBtn>
                <StarBtn
                  active={isFav}
                  title={isFav ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}
                  onClick={(e) => { e.stopPropagation(); onToggleFav(entry); }}
                >
                  <Star size={12} fill={isFav ? 'currentColor' : 'none'} />
                </StarBtn>
              </EntryRow>
            );
          })}
        </SectionInner>
      </SectionBody>
    </SectionWrap>
  );
}

// ─── Sidebar ──────────────────────────────────────────────────────────────────

interface SidebarProps {
  config: NavigationConfig;
  activeId: string | null;
  onSelect: (entry: NavEntry) => void;
  hashPrefix: string;
}

export function Sidebar({ config, activeId, onSelect, hashPrefix }: SidebarProps) {
  const rKey = `atlantis-recent-${hashPrefix}`;
  const fKey = `atlantis-fav-${hashPrefix}`;
  const { collapsed } = useSidebar();

  const [recent, setRecent] = useState<NavEntry[]>(() => loadStored(rKey));
  const [favs, setFavs] = useState<NavEntry[]>(() => loadStored(fKey));

  const handleSelect = useCallback((entry: NavEntry) => {
    if (entry.file) {
      setRecent((prev) => pushRecent(rKey, entry, prev));
    }
    onSelect(entry);
  }, [onSelect, rKey]);

  const handleToggleFav = useCallback((entry: NavEntry) => {
    setFavs((prev) => toggleFav(fKey, entry, prev));
  }, [fKey]);

  return (
    <Nav>
      <QuickSection
        title="Recentes"
        icon={<Clock size={13} />}
        entries={recent}
        activeId={activeId}
        onSelect={handleSelect}
        favorites={favs}
        onToggleFav={handleToggleFav}
        collapsed={collapsed}
      />
      <QuickSection
        title="Favoritos"
        icon={<Star size={13} />}
        entries={favs}
        activeId={activeId}
        onSelect={handleSelect}
        favorites={favs}
        onToggleFav={handleToggleFav}
        collapsed={collapsed}
      />
      <NavTree entries={config.entries} activeId={activeId} onSelect={handleSelect} />
    </Nav>
  );
}

export default Sidebar;
