import { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { Global, css } from '@emotion/react';
import { Sun, Moon, Monitor } from 'lucide-react';
import styled from '@emotion/styled';
import { generateCSSVariables, theme } from '../theme';

// ─── Types ───────────────────────────────────────────────────────────────────

export type ThemeMode = 'dark' | 'light' | 'system';
type ResolvedMode = 'dark' | 'light';

interface ThemeContextValue {
  mode: ThemeMode;
  resolvedMode: ResolvedMode;
  setMode: (mode: ThemeMode) => void;
}

// ─── Context ─────────────────────────────────────────────────────────────────

const ThemeContext = createContext<ThemeContextValue>({
  mode: 'dark',
  resolvedMode: 'dark',
  setMode: () => {},
});

const STORAGE_KEY = 'atlantis:theme-mode';

function getSystemPreference(): ResolvedMode {
  if (typeof window === 'undefined') return 'dark';
  return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
}

/**
 * Idempotently inject the Atlantis webfonts (Inter / JetBrains Mono /
 * Cormorant Garamond). The shell's `index.html` already includes these so
 * production boots with them pre-loaded; this injection covers standalone
 * dev (running a single remote's own dev server) so visuals stay consistent.
 */
const FONTS_LINK_ID = 'atlantis-webfonts';
const FONTS_HREF =
  'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800' +
  '&family=JetBrains+Mono:wght@400;500;600' +
  '&family=Cormorant+Garamond:wght@400;500;600;700&display=swap';

function ensureWebfonts(): void {
  if (typeof document === 'undefined') return;
  if (document.getElementById(FONTS_LINK_ID)) return;
  const link = document.createElement('link');
  link.id = FONTS_LINK_ID;
  link.rel = 'stylesheet';
  link.href = FONTS_HREF;
  document.head.appendChild(link);
}

function resolveMode(mode: ThemeMode): ResolvedMode {
  return mode === 'system' ? getSystemPreference() : mode;
}

// ─── Global styles ───────────────────────────────────────────────────────────

function ThemeGlobalStyles({ resolvedMode }: { resolvedMode: ResolvedMode }) {
  const variables = useMemo(() => generateCSSVariables(resolvedMode), [resolvedMode]);

  return (
    <Global
      styles={css`
        :root {
          ${variables}
        }

        html {
          color-scheme: ${resolvedMode};
        }

        body {
          background: var(--at-mainBg);
          color: var(--at-mainText);
          font-family: ${theme.typography.fontFamily};
          font-size: ${theme.typography.fontSizeBase};
          line-height: ${theme.typography.lineHeightBase};
          -webkit-font-smoothing: antialiased;
          -moz-osx-font-smoothing: grayscale;
          text-rendering: optimizeLegibility;
          transition: background 0.3s ease, color 0.3s ease;
        }

        /* Inherit by default — every app gets Inter without restating it. */
        button, input, textarea, select {
          font-family: inherit;
        }
        code, kbd, pre, samp {
          font-family: ${theme.typography.fontFamilyMono};
        }

        /* Scrollbar */
        ::-webkit-scrollbar {
          width: 8px;
          height: 8px;
        }
        ::-webkit-scrollbar-track {
          background: transparent;
        }
        ::-webkit-scrollbar-thumb {
          background: var(--at-border);
          border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
          background: var(--at-mainTextMuted);
        }

        * {
          scrollbar-width: thin;
          scrollbar-color: var(--at-border) transparent;
        }

        /* Selection */
        ::selection {
          background: var(--at-accentMuted);
          color: var(--at-mainText);
        }

        /* Focus visible */
        :focus-visible {
          outline: 2px solid var(--at-accent);
          outline-offset: 2px;
        }
      `}
    />
  );
}

// ─── Provider ────────────────────────────────────────────────────────────────

interface ThemeProviderProps {
  children: React.ReactNode;
}

export function ThemeProvider({ children }: ThemeProviderProps) {
  const [mode, setModeState] = useState<ThemeMode>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored === 'dark' || stored === 'light' || stored === 'system') return stored;
    } catch {}
    return 'dark';
  });

  const [resolvedMode, setResolvedMode] = useState<ResolvedMode>(() => resolveMode(mode));

  const setMode = useCallback((newMode: ThemeMode) => {
    setModeState(newMode);
    try { localStorage.setItem(STORAGE_KEY, newMode); } catch {}
  }, []);

  // Listen to system preference changes
  useEffect(() => {
    if (mode !== 'system') {
      setResolvedMode(mode);
      return;
    }

    setResolvedMode(getSystemPreference());

    const mq = window.matchMedia('(prefers-color-scheme: light)');
    const handler = (e: MediaQueryListEvent) => {
      setResolvedMode(e.matches ? 'light' : 'dark');
    };
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [mode]);

  // Set data attribute on html for consumers that need it
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', resolvedMode);
  }, [resolvedMode]);

  // Ensure the webfonts are loaded — covers standalone-dev remotes.
  useEffect(() => { ensureWebfonts(); }, []);

  const value = useMemo(() => ({ mode, resolvedMode, setMode }), [mode, resolvedMode, setMode]);

  return (
    <ThemeContext.Provider value={value}>
      <ThemeGlobalStyles resolvedMode={resolvedMode} />
      {children}
    </ThemeContext.Provider>
  );
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export function useThemeMode() {
  return useContext(ThemeContext);
}

// ─── Toggle component ────────────────────────────────────────────────────────

const ToggleBtn = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: none;
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.md};
  cursor: pointer;
  color: ${theme.colors.mainTextMuted};
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.2s;

  &:hover {
    background: ${theme.colors.sidebarHover};
    color: ${theme.colors.accent};
    border-color: ${theme.colors.accent};
  }

  &:active {
    transform: scale(0.92);
  }

  svg {
    transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  &:hover svg {
    transform: rotate(15deg);
  }
`;

const MODES: ThemeMode[] = ['dark', 'light', 'system'];
const MODE_ICONS = {
  dark: Moon,
  light: Sun,
  system: Monitor,
} as const;
const MODE_LABELS = {
  dark: 'Dark mode (click for light)',
  light: 'Light mode (click for system)',
  system: 'System mode (click for dark)',
} as const;

export function ThemeToggle() {
  const { mode, setMode } = useThemeMode();

  const cycleMode = () => {
    const idx = MODES.indexOf(mode);
    setMode(MODES[(idx + 1) % MODES.length]);
  };

  const Icon = MODE_ICONS[mode];

  return (
    <ToggleBtn onClick={cycleMode} title={MODE_LABELS[mode]}>
      <Icon size={16} strokeWidth={1.75} />
    </ToggleBtn>
  );
}
